"""Thin wrapper around the neatlogs SDK so tracing never breaks an audit.

- init_tracing(): one-time SDK init with a secret-redacting mask.
- audit_context(): binds audit id + run kind ("test"/"real") to every span in an audit.
- event(): a timestamped step (retry, fallback, ...) inside the current span.
"""
import json
import logging
import re
import sys
from contextlib import ExitStack, contextmanager

from app import config

log = logging.getLogger(__name__)
_enabled = False

_SECRET_RX = re.compile(
    r"(gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}|gsk_[A-Za-z0-9]{20,}"
    r"|ygbnp_[A-Za-z0-9]{16,}|Bearer\s+[A-Za-z0-9._\-]{16,})"
)


def redact(value):
    """Recursively replace anything that looks like one of our secrets."""
    if isinstance(value, str):
        out = _SECRET_RX.sub("[REDACTED]", value)
        for secret in (config.GITHUB_TOKEN, config.GROQ_API_KEY, config.NEATLOGS_API_KEY):
            if secret and len(secret) > 8:
                out = out.replace(secret, "[REDACTED]")
        return out
    if isinstance(value, dict):
        return {k: redact(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return type(value)(redact(v) for v in value)
    return value


def _mask(span: dict) -> dict:
    return redact(span)


def init_tracing(workflow_name: str = "prejudge") -> bool:
    """Initialise neatlogs once. Returns False (and keeps running) if unavailable."""
    global _enabled
    if _enabled:
        return True
    if not config.NEATLOGS_API_KEY:
        log.info("NEATLOGS_API_KEY not set; tracing disabled")
        return False
    try:
        import neatlogs

        neatlogs.init(
            api_key=config.NEATLOGS_API_KEY,
            workflow_name=workflow_name,
            tags=["neatHack", "prejudge"],
            mask=_mask,
        )
        _enabled = True
        # The SDK logs to stdout; move it to stderr so CLI stdout stays pure JSON.
        for h in logging.getLogger("neatlogs").handlers:
            if isinstance(h, logging.StreamHandler) and getattr(h, "stream", None) is sys.stdout:
                h.setStream(sys.stderr)
    except Exception as exc:  # tracing must never take the app down
        log.warning("neatlogs init failed: %s", type(exc).__name__)
    return _enabled


def span(kind: str, name: str | None = None, **kwargs):
    """neatlogs.span decorator, or a no-op if the SDK can't be imported."""
    def deco(fn):
        try:
            import neatlogs

            return neatlogs.span(kind, name, **kwargs)(fn)
        except Exception:
            return fn

    return deco


@contextmanager
def audit_context(audit_id: str, run_kind: str, repo_url: str):
    """Group every span of one audit under its id, tagged test/real for filtering."""
    with ExitStack() as stack:
        if _enabled:
            try:
                import neatlogs

                stack.enter_context(neatlogs.identify(session_id=audit_id))
                stack.enter_context(neatlogs.trace(
                    "prejudge.audit",
                    session_id=audit_id,
                    **{
                        "tag.tags": ["prejudge", run_kind],
                        "metadata": json.dumps(
                            {"audit_id": audit_id, "run_kind": run_kind, "repo_url": repo_url}
                        ),
                    },
                ))
            except Exception as exc:
                log.warning("neatlogs audit context failed: %s", type(exc).__name__)
        yield


def event(message: str, level: str = "info", **data) -> None:
    """Record a retry/fallback/failure as a timestamped event in the active span."""
    if not _enabled:
        return
    try:
        import neatlogs

        neatlogs.log(message, level=level, **redact(data))
    except Exception:
        pass


def flush() -> None:
    if not _enabled:
        return
    try:
        import neatlogs

        neatlogs.flush(timeout_millis=10_000)
    except Exception:
        pass

"""Tools the LLM may call during claim verification.

All arguments come from the LLM, which has read untrusted repo text, so every
argument is validated: paths must name something in this repo's tree, URLs go
through the M1 link checker's SSRF guard. All output is wrapped as UNTRUSTED DATA.
"""
import json
import posixpath
import re

from app.agent.prompts import untrusted
from app.steps import StepLog
from app.tools.github import GitHubClient, GitHubError, RepoRef
from app.tools.links import check_links
from app.tracing import span

MAX_FILES_READ = 10
READ_FILE_CHARS = 4000
MAX_LIST_ENTRIES = 80
MAX_URL_LEN = 2000


class ToolArgError(ValueError):
    kind = "invalid_tool_args"


TOOL_SCHEMAS = [
    {"type": "function", "function": {
        "name": "list_files",
        "description": "List files and folders under a directory of the audited repo ('' for root).",
        "parameters": {"type": "object", "properties": {
            "path": {"type": "string", "description": "repo-relative directory, '' for root"}},
            "required": ["path"]}}},
    {"type": "function", "function": {
        "name": "read_file",
        "description": f"Read a repo file (first {READ_FILE_CHARS} chars, with line numbers). "
                       f"At most {MAX_FILES_READ} distinct files per audit.",
        "parameters": {"type": "object", "properties": {
            "path": {"type": "string", "description": "repo-relative file path from list_files"}},
            "required": ["path"]}}},
    {"type": "function", "function": {
        "name": "get_commits",
        "description": "Most recent commits: short sha, ISO date, first line of message.",
        "parameters": {"type": "object", "properties": {
            "limit": {"type": "integer", "minimum": 1, "maximum": 50}},
            "required": ["limit"]}}},
    {"type": "function", "function": {
        "name": "check_link",
        "description": "Check whether an http(s) URL is reachable; returns status code.",
        "parameters": {"type": "object", "properties": {
            "url": {"type": "string"}}, "required": ["url"]}}},
]


def safe_repo_path(path, tree_paths: set[str], *, is_dir: bool = False) -> str:
    """Normalise an LLM-supplied path and make sure it stays inside the repo."""
    if not isinstance(path, str):
        raise ToolArgError("path must be a string")
    p = path.strip()
    if "\x00" in p or "\\" in p or re.match(r"^[a-z]+://", p, re.I):
        raise ToolArgError(f"invalid path: {path!r}")
    if p.startswith("/") or p.startswith("~"):
        raise ToolArgError(f"absolute paths are not allowed: {path!r}")
    if ".." in p.split("/"):
        raise ToolArgError(f"path escapes the repo: {path!r}")
    p = posixpath.normpath(p) if p else ""
    if p == ".":
        p = ""
    if is_dir:
        if p and not any(t.startswith(p + "/") for t in tree_paths):
            raise ToolArgError(f"no such directory in repo: {p!r}")
    elif p not in tree_paths:
        raise ToolArgError(f"no such file in repo: {p!r}")
    return p


def safe_url(url) -> str:
    if not isinstance(url, str) or len(url) > MAX_URL_LEN:
        raise ToolArgError("url must be a string under 2000 chars")
    u = url.strip()
    if not re.match(r"^https?://[^\s/]+", u, re.I):
        raise ToolArgError(f"only http(s) URLs are allowed: {url!r}")
    return u


class RepoToolbox:
    def __init__(self, gh: GitHubClient | None, ref: RepoRef | None, branch: str,
                 tree_paths: list[str], commits: list[dict] | None, steps: StepLog):
        self.gh, self.ref, self.branch = gh, ref, branch
        self.tree = set(tree_paths)
        self.commits = commits or []
        self.steps = steps
        self.files_read: dict[str, str] = {}
        self.calls = 0

    async def dispatch(self, name: str, raw_args: str | None) -> str:
        """Run one tool call. Never raises: errors go back to the LLM as text and into the step log."""
        self.calls += 1
        with self.steps.step(f"tool.{name}") as s:
            try:
                args = json.loads(raw_args or "{}")
                if not isinstance(args, dict):
                    raise ToolArgError("arguments must be a JSON object")
            except json.JSONDecodeError as exc:
                raise ToolArgError(f"arguments are not valid JSON: {exc}") from exc
            s.data["args"] = {k: str(v)[:200] for k, v in args.items()}
            fn = {"list_files": self.list_files, "read_file": self.read_file,
                  "get_commits": self.get_commits, "check_link": self.check_link}.get(name)
            if fn is None:
                raise ToolArgError(f"unknown tool {name!r}")
            out = await fn(**{k: v for k, v in args.items() if k in ("path", "limit", "url")})
            s.detail = f"{len(out)} chars"
            return out
        # reached only if the step recorded a failure
        failed = self.steps.steps[-1]
        return f"ERROR ({failed.error_kind}): {failed.detail}"

    @span("TOOL", "agent.list_files")
    async def list_files(self, path: str = "") -> str:
        p = safe_repo_path(path, self.tree, is_dir=True)
        prefix = p + "/" if p else ""
        entries = set()
        for t in self.tree:
            if t.startswith(prefix):
                head, _, rest = t[len(prefix):].partition("/")
                entries.add(head + ("/" if rest else ""))
        listing = sorted(entries)
        more = f"\n... {len(listing) - MAX_LIST_ENTRIES} more" if len(listing) > MAX_LIST_ENTRIES else ""
        return untrusted(f"list_files:{p or '/'}", "\n".join(listing[:MAX_LIST_ENTRIES]) + more)

    @span("TOOL", "agent.read_file")
    async def read_file(self, path: str) -> str:
        p = safe_repo_path(path, self.tree)
        if p not in self.files_read:
            if len(self.files_read) >= MAX_FILES_READ:
                raise ToolArgError(f"file budget used up ({MAX_FILES_READ} files); decide with what you have")
            if self.gh is None or self.ref is None:
                raise ToolArgError("repo contents unavailable")
            try:
                text = await self.gh.get_file(self.ref, p, self.branch)
            except GitHubError as exc:
                raise ToolArgError(f"could not read {p}: {exc.kind}") from exc
            numbered = "\n".join(f"{i}: {line}" for i, line in enumerate(text.splitlines(), 1))
            if len(numbered) > READ_FILE_CHARS:
                numbered = numbered[:READ_FILE_CHARS] + f"\n[truncated; file is {len(text)} chars]"
            self.files_read[p] = numbered
        return untrusted(f"file:{p}", self.files_read[p])

    @span("TOOL", "agent.get_commits")
    async def get_commits(self, limit: int = 20) -> str:
        try:
            n = max(1, min(int(limit), 50))
        except (TypeError, ValueError) as exc:
            raise ToolArgError("limit must be an integer") from exc
        lines = [f"{c['sha']} {c['committed_at']} {c['message']}" for c in self.commits[:n]]
        return untrusted("commits", "\n".join(lines) or "(no commits available)")

    @span("TOOL", "agent.check_link")
    async def check_link(self, url: str) -> str:
        u = safe_url(url)
        [r] = await check_links([u])  # SSRF guard lives in the link checker
        return json.dumps({k: r[k] for k in ("url", "status", "ok", "error", "final_url")})

"""Strict schemas for every JSON the LLM returns."""
import json
import re
from typing import Literal

from pydantic import BaseModel, Field, field_validator

Category = Literal["agent", "tools", "demo_video", "building_in_public", "usefulness"]
MAX_CLAIMS = 8

_PROFANITY = re.compile(
    r"\b(fuck\w*|shit\w*|bitch\w*|bastard\w*|asshole\w*|dick(head)?s?|cunt\w*|crap|damn\w*|wtf)\b", re.I)


class Claim(BaseModel):
    id: str = Field(max_length=10)
    text: str = Field(min_length=3, max_length=300)
    quote: str = Field(default="", max_length=300)
    category: Category = "agent"


class ClaimList(BaseModel):
    claims: list[Claim] = Field(default_factory=list)
    injection_attempts: list[str] = Field(default_factory=list)

    @field_validator("claims")
    @classmethod
    def cap(cls, v: list[Claim]) -> list[Claim]:
        seen, out = set(), []
        for c in v:
            if c.id not in seen:
                seen.add(c.id)
                out.append(c)
        return out[:MAX_CLAIMS]


class Evidence(BaseModel):
    ref: str = Field(max_length=500)
    note: str = Field(default="", max_length=300)


class ClaimResult(BaseModel):
    claim_id: str
    status: Literal["verified", "unverified", "contradicted"]
    evidence: list[Evidence] = Field(default_factory=list)
    reason: str = Field(default="", max_length=500)


class Estimate(BaseModel):
    score: float = Field(ge=0, le=10)
    evidence: list[str] = Field(default_factory=list)
    reason: str = Field(default="", max_length=500)


class VerifyResult(BaseModel):
    results: list[ClaimResult] = Field(default_factory=list)
    estimates: dict[Literal["agent_quality", "usefulness"], Estimate] = Field(default_factory=dict)
    injection_attempts: list[str] = Field(default_factory=list)


class FixItem(BaseModel):
    check_id: str
    fix: str = Field(min_length=5, max_length=400)


class Verdict(BaseModel):
    roast: str = Field(min_length=10, max_length=450)
    fixes: list[FixItem] = Field(default_factory=list)
    best_thing: str = Field(min_length=5, max_length=300)

    @field_validator("roast")
    @classmethod
    def short_and_clean(cls, v: str) -> str:
        sentences = [s for s in re.split(r"(?<=[.!?])\s+", v.strip()) if s]
        if len(sentences) > 3:
            raise ValueError(f"roast must be 1-3 sentences, got {len(sentences)}")
        return v.strip()

    @field_validator("roast", "best_thing")
    @classmethod
    def no_profanity(cls, v: str) -> str:
        if _PROFANITY.search(v):
            raise ValueError("no profanity allowed")
        return v


def parse_json(text: str | None, model: type[BaseModel]) -> BaseModel:
    """Parse model output (tolerating ```json fences) and validate. Raises ValueError."""
    if not text:
        raise ValueError("empty response")
    t = text.strip()
    fence = re.match(r"^```(?:json)?\s*(.*?)\s*```$", t, re.S)
    if fence:
        t = fence.group(1)
    try:
        data = json.loads(t)
    except json.JSONDecodeError as exc:
        raise ValueError(f"invalid JSON: {exc}") from exc
    return model.model_validate(data)

