"""Record / replay of LLM responses, so the app and tests run without spending Groq tokens.

LLM_MODE=live    (default) real Groq calls
LLM_MODE=record  real calls, and each response is saved under fixtures/llm/<owner>__<repo>.json
LLM_MODE=replay  no network for the LLM: answers come from those fixtures; a repo without a
                 fixture behaves like an LLM outage (template verdict, honestly labelled)

Fixtures are keyed by repo and purpose (quick_verdict, claims, verify, verdict). Replayed
claim evidence still goes through grounding: the replayed verify turn asks to read the cited
files from the real repo, so nothing "verified" is taken on trust from the fixture.
"""
import contextvars
import json
import re
from contextlib import contextmanager
from pathlib import Path
from types import SimpleNamespace

from app import config

FIXTURE_DIR = Path(__file__).resolve().parent.parent / "fixtures" / "llm"
_repo: contextvars.ContextVar[str | None] = contextvars.ContextVar("replay_repo", default=None)


class ReplayMiss(Exception):
    """No fixture for this repo/purpose."""


def mode() -> str:
    m = config.env("LLM_MODE", "live").lower()
    return m if m in ("live", "replay", "record") else "live"


@contextmanager
def repo_context(full_name: str | None):
    token = _repo.set((full_name or "").lower() or None)
    try:
        yield
    finally:
        _repo.reset(token)


def current_repo() -> str | None:
    return _repo.get()


def fixture_path(repo: str) -> Path:
    return FIXTURE_DIR / (re.sub(r"[^a-z0-9._-]+", "__", repo.lower()) + ".json")


def load(repo: str | None) -> dict | None:
    if not repo:
        return None
    p = fixture_path(repo)
    if not p.exists():
        return None
    return json.loads(p.read_text())


def _base(purpose: str) -> str:
    return purpose.split(".")[0]


def _message(content=None, tool_calls=None, tokens: int = 0):
    calls = None
    if tool_calls:
        calls = [SimpleNamespace(id=f"replay_{i}", type="function",
                                 function=SimpleNamespace(name=c["name"], arguments=json.dumps(c["arguments"])))
                 for i, c in enumerate(tool_calls)]
    msg = SimpleNamespace(role="assistant", content=json.dumps(content) if isinstance(content, (dict, list)) else content,
                          tool_calls=calls)
    usage = SimpleNamespace(prompt_tokens=int(tokens * 0.85), completion_tokens=tokens - int(tokens * 0.85),
                            total_tokens=tokens)
    return msg, usage


def respond(purpose: str, messages: list[dict], tools: list | None):
    """-> (message, usage) for this purpose, or ReplayMiss."""
    fx = load(current_repo())
    if fx is None:
        raise ReplayMiss(f"no LLM fixture for {current_repo() or 'unknown repo'}")
    responses, usage = fx.get("responses", {}), fx.get("usage", {})
    base = _base(purpose)
    tokens = int(usage.get(base, 0))
    if purpose.endswith("roast_retry"):
        verdict = responses.get(base) or {}
        if "roast" not in verdict:
            raise ReplayMiss(f"no roast for {purpose}")
        return _message({"roast": verdict["roast"]}, tokens=tokens)
    if base == "verify":
        already_used_tools = any(m.get("role") == "tool" for m in messages)
        if tools and not already_used_tools and fx.get("verify_tool_calls"):
            return _message(tool_calls=fx["verify_tool_calls"], tokens=tokens)
    if base not in responses:
        raise ReplayMiss(f"no {base} response in fixture for {current_repo()}")
    return _message(responses[base], tokens=tokens)


def record(purpose: str, message, usage) -> None:
    """LLM_MODE=record: keep the first response per purpose for this repo."""
    repo = current_repo()
    if not repo:
        return
    FIXTURE_DIR.mkdir(parents=True, exist_ok=True)
    p = fixture_path(repo)
    fx = json.loads(p.read_text()) if p.exists() else {"repo": repo, "source": "recorded (LLM_MODE=record)",
                                                       "responses": {}, "usage": {}}
    base = _base(purpose)
    if message.tool_calls:
        if base == "verify" and "verify_tool_calls" not in fx:
            fx["verify_tool_calls"] = [{"name": c.function.name, "arguments": json.loads(c.function.arguments or "{}")}
                                       for c in message.tool_calls]
    elif base not in fx["responses"] and message.content:
        try:
            fx["responses"][base] = json.loads(message.content)
        except ValueError:
            return
        fx["usage"][base] = getattr(usage, "total_tokens", 0) or 0
    p.write_text(json.dumps(fx, indent=2, ensure_ascii=False))

"""Audit queues: quick by default, deep on request.

quick lane -> deterministic checks + short verdict, saved as "quick_ready"
deep lane  -> only when asked (POST /api/audits/{id}/deep): claim verification + rescore,
              saved as "complete"; one at a time, low LLM priority

The deep lane never degrades to a weaker model: if no JUDGE_MODELS have daily budget it
waits (phase_deep = "waiting_budget") and retries, keeping its place in the queue.
"""
import asyncio
import logging
import time
from collections import OrderedDict, deque

from app import db, replay
from app.llm import POOL, BudgetExhausted, judge_models
from app.steps import StepLog

log = logging.getLogger(__name__)
QUICK_TIMEOUT_S = 60
DEEP_TIMEOUT_S = 180
DEEP_EST_TOKENS = 16_000        # measured average deep phase (EVIDENCE.md)
BUDGET_RECHECK_S = 120          # how often a waiting deep audit re-checks the budget
CTX_CACHE_SIZE = 50             # quick-phase context kept for a later deep request


async def _run_quick(repo_url: str, audit_id: str, run_kind: str, steps: StepLog, ctx: dict,
                     use_reserve: bool = False) -> dict:
    from app.audit import run_quick_audit  # lazy, so tests can patch these

    return await run_quick_audit(repo_url, audit_id=audit_id, run_kind=run_kind, log=steps, ctx=ctx,
                                 use_reserve=use_reserve)


async def _run_deep(report: dict, ctx: dict, steps: StepLog, use_reserve: bool = False) -> dict:
    from app.audit import run_deep_audit

    return await run_deep_audit(report, ctx, log=steps, use_reserve=use_reserve)


async def _rebuild_ctx(report: dict) -> dict:
    from app.audit import rebuild_context

    return await rebuild_context(report)


def deep_budget_ok(use_reserve: bool) -> bool:
    if replay.mode() == "replay":
        return True  # replay spends no tokens
    return any(POOL.daily_ok(m, DEEP_EST_TOKENS, use_reserve) for m in judge_models())


def cacheable(result: dict) -> bool:
    """Reuse only results the LLM actually wrote; a template (cooling) verdict should be retried."""
    return (result.get("verdict") or {}).get("source") == "llm"


class Lane:
    """A FIFO lane with one worker, visible positions and a moving-average duration."""

    def __init__(self, name: str, default_s: float):
        self.name = name
        self.pending: deque = deque()
        self.running: tuple[str, float] | None = None     # (audit_id, started_at)
        self.avg_s = default_s
        self.waiting_budget = False
        self._wake: asyncio.Event | None = None

    def start(self) -> None:
        self._wake = asyncio.Event()

    def put(self, audit_id: str, payload, front: bool = False) -> None:
        (self.pending.appendleft if front else self.pending.append)((audit_id, payload))
        self._wake.set()

    def __contains__(self, audit_id: str) -> bool:
        return (self.running and self.running[0] == audit_id) or any(a == audit_id for a, _ in self.pending)

    async def get(self):
        while not self.pending:
            self._wake.clear()
            await self._wake.wait()
        return self.pending.popleft()

    def observe(self, seconds: float) -> None:
        self.avg_s = 0.7 * self.avg_s + 0.3 * seconds

    def length(self) -> int:
        return len(self.pending) + (1 if self.running else 0)

    def position(self, audit_id: str) -> dict | None:
        """1 = running now; n = n-1 audits ahead of it. None if not in this lane."""
        now = time.monotonic()
        current_left = max(0.0, self.avg_s - (now - self.running[1])) if self.running else 0.0
        base = {"lane": self.name, "waiting_for_budget": self.waiting_budget}
        if self.running and self.running[0] == audit_id:
            return {**base, "position": 1, "estimated_wait_s": round(current_left)}
        for i, (aid, _) in enumerate(self.pending):
            if aid == audit_id:
                ahead = i + (1 if self.running else 0)
                return {**base, "position": ahead + 1,
                        "estimated_wait_s": round(current_left + i * self.avg_s + self.avg_s)}
        return None


class AuditQueues:
    def __init__(self) -> None:
        self.quick = Lane("quick", default_s=10)
        self.deep = Lane("deep", default_s=45)
        self.ctx_cache: OrderedDict[str, dict] = OrderedDict()
        self._tasks: list[asyncio.Task] = []

    def start(self) -> None:
        self.quick.start()
        self.deep.start()
        self._tasks = [asyncio.create_task(self._quick_worker()),
                       asyncio.create_task(self._deep_worker())]

    async def stop(self) -> None:
        for t in self._tasks:
            t.cancel()
        for t in self._tasks:
            try:
                await t
            except asyncio.CancelledError:
                pass

    async def submit(self, audit_id: str, repo_url: str, run_kind: str, use_reserve: bool = False) -> dict:
        self.quick.put(audit_id, (repo_url, run_kind, use_reserve))
        return self.position(audit_id)

    def request_deep(self, audit_id: str, use_reserve: bool = False) -> dict:
        if audit_id not in self.deep:
            db.update(audit_id, phase_deep="queued")
            self.deep.put(audit_id, use_reserve)
        return self.position(audit_id)

    def position(self, audit_id: str) -> dict | None:
        return self.quick.position(audit_id) or self.deep.position(audit_id)

    def _remember_ctx(self, audit_id: str, ctx: dict) -> None:
        self.ctx_cache[audit_id] = ctx
        self.ctx_cache.move_to_end(audit_id)
        while len(self.ctx_cache) > CTX_CACHE_SIZE:
            self.ctx_cache.popitem(last=False)

    # ---------------------------------------------------------------- workers

    async def _quick_worker(self) -> None:
        while True:
            audit_id, (repo_url, run_kind, use_reserve) = await self.quick.get()
            self.quick.running = (audit_id, time.monotonic())
            try:
                await self._quick(audit_id, repo_url, run_kind, use_reserve)
            except Exception:
                log.exception("quick phase crashed for %s", audit_id)
            finally:
                self.quick.observe(time.monotonic() - self.quick.running[1])
                self.quick.running = None

    async def _quick(self, audit_id: str, repo_url: str, run_kind: str, use_reserve: bool) -> None:
        db.update(audit_id, phase_quick="running")
        steps = StepLog(on_change=lambda s: db.update(audit_id, steps=s.to_list()))
        ctx: dict = {}
        try:
            report = await asyncio.wait_for(_run_quick(repo_url, audit_id, run_kind, steps, ctx, use_reserve),
                                            QUICK_TIMEOUT_S)
        except Exception as exc:  # timeout or bug: keep the steps so far as a partial record
            steps.note("quick.crashed", f"{type(exc).__name__}: {str(exc)[:200]}", status="failed")
            db.update(audit_id, status="failed", phase_quick="failed", phase_deep="skipped",
                      error=type(exc).__name__, steps=steps.to_list())
            return
        deep_state = "available" if ctx.get("repo_available") else "skipped"
        db.update(audit_id, status="quick_ready", phase_quick="done", phase_deep=deep_state,
                  steps=report.get("steps", steps.to_list()), result=report,
                  **({} if cacheable(report) else {"head_sha": None}))
        if ctx.get("repo_available"):
            self._remember_ctx(audit_id, ctx)

    async def _deep_worker(self) -> None:
        while True:
            audit_id, use_reserve = await self.deep.get()
            if not deep_budget_ok(use_reserve):
                await self._wait_for_budget(audit_id, use_reserve)
                continue
            self.deep.running = (audit_id, time.monotonic())
            try:
                await self._deep(audit_id, use_reserve)
            except Exception:
                log.exception("deep phase crashed for %s", audit_id)
            finally:
                self.deep.observe(time.monotonic() - self.deep.running[1])
                self.deep.running = None

    async def _wait_for_budget(self, audit_id: str, use_reserve: bool, retry_in: float | None = None) -> None:
        """Keep the audit at the head of the deep queue until a judge model has budget."""
        self.deep.waiting_budget = True
        db.update(audit_id, phase_deep="waiting_budget")
        self.deep.put(audit_id, use_reserve, front=True)
        await asyncio.sleep(min(retry_in or BUDGET_RECHECK_S, BUDGET_RECHECK_S))
        self.deep.waiting_budget = not deep_budget_ok(use_reserve)

    async def _deep(self, audit_id: str, use_reserve: bool) -> None:
        row = db.get(audit_id)
        if row is None or not row["result"]:
            return
        report = row["result"]
        db.update(audit_id, phase_deep="running")
        steps = StepLog.from_list(row["steps"], on_change=lambda s: db.update(audit_id, steps=s.to_list()))
        try:
            ctx = self.ctx_cache.get(audit_id)
            if ctx is None:
                steps.note("deep.rebuild_context", "quick-phase context expired; re-reading the repo (no LLM)")
                ctx = await _rebuild_ctx(report)
            result = await asyncio.wait_for(_run_deep(report, ctx, steps, use_reserve), DEEP_TIMEOUT_S)
        except BudgetExhausted as exc:
            steps.note("deep.waiting_budget", f"{exc}; waiting instead of using a weaker model")
            db.update(audit_id, steps=steps.to_list())
            await self._wait_for_budget(audit_id, use_reserve, exc.retry_in_s)
            return
        except Exception as exc:
            # The quick result stays available; the audit is just not deepened.
            steps.note("deep.crashed", f"{type(exc).__name__}: {str(exc)[:200]}", status="failed")
            db.update(audit_id, phase_deep="failed", error=f"deep: {type(exc).__name__}", steps=steps.to_list())
            return
        self.ctx_cache.pop(audit_id, None)
        db.update(audit_id, status="complete", phase_deep="done", steps=result.get("steps", steps.to_list()),
                  result=result, **({} if cacheable(result) else {"head_sha": None}))

    # ---------------------------------------------------------------- health

    def busy(self) -> bool:
        return self.deep.length() >= 4 or self.deep.avg_s * self.deep.length() > 300

"""FastAPI routes.

POST /api/audits {repo_url}          -> quick phase only: {id, status, cached}
POST /api/audits/{id}/deep           -> queue the deep phase: {queue: {position, estimated_wait_s}}
GET  /api/audits/{id}                -> status, phases, queue position + ETA, steps, result
POST /api/audits/{id}/feedback       -> "this verdict is wrong" for a check or claim
GET  /api/stats                      -> public counter + budget state (normal | busy | cooling)
GET  /api/examples                   -> saved example audits for the home page

Status: queued -> quick_ready -> complete | failed. Deep phase: available -> queued ->
(waiting_budget) -> running -> done | failed | skipped.
Requests with a valid X-Admin-Token header may use the reserved share of the LLM budget.
"""
import hmac
import uuid
from contextlib import asynccontextmanager
from typing import Literal

from fastapi import FastAPI, Header, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, Field

from app import budget, config, db, replay
from app.jobs import AuditQueues
from app.llm import POOL, configured_models
from app.tools.github import GitHubClient, GitHubError, parse_repo_url
from app.tracing import flush, init_tracing

queues = AuditQueues()


@asynccontextmanager
async def lifespan(_: FastAPI):
    init_tracing()
    db.connect()
    db.mark_interrupted()
    db.seed_examples()
    budget.attach(POOL)
    queues.start()
    yield
    await queues.stop()
    flush()


app = FastAPI(title="PreJudge", lifespan=lifespan)
app.add_middleware(
    CORSMiddleware,
    allow_origins=[o.strip() for o in config.env("CORS_ORIGINS", "http://localhost:5173").split(",")],
    allow_methods=["GET", "POST"],
    allow_headers=["Content-Type", "X-Admin-Token"],
)


class AuditRequest(BaseModel):
    repo_url: str = Field(min_length=3, max_length=300)
    run_kind: Literal["real", "test"] = "real"


class FeedbackRequest(BaseModel):
    check_id: str = Field(min_length=1, max_length=100)
    is_wrong: bool = True
    note: str = Field(default="", max_length=500)


def is_admin(token: str | None) -> bool:
    expected = config.env("ADMIN_TOKEN")
    return bool(expected and token and hmac.compare_digest(token, expected))


async def resolve_head_sha(repo_url: str) -> str | None:
    """Latest commit SHA for the cache key; None if GitHub can't tell us (the audit will say why)."""
    try:
        async with GitHubClient() as gh:
            return await gh.get_head_sha(parse_repo_url(repo_url))
    except GitHubError:
        return None


def _get(audit_id: str) -> dict:
    row = db.get(audit_id)
    if row is None:
        raise HTTPException(404, "audit not found")
    return row


@app.get("/api/health")
def health() -> dict:
    return {"ok": True, "llm_mode": replay.mode()}


@app.post("/api/audits", status_code=202, responses={400: {"description": "Not a GitHub repo URL"}})
async def create_audit(req: AuditRequest, x_admin_token: str | None = Header(default=None)) -> dict:
    try:
        ref = parse_repo_url(req.repo_url)
    except GitHubError as exc:
        raise HTTPException(400, str(exc)) from exc
    repo_key = ref.full_name.lower()
    head_sha = await resolve_head_sha(req.repo_url)
    audit_id = uuid.uuid4().hex[:12]

    if head_sha:
        cached = db.find_cached(repo_key, head_sha)
        if cached:
            result = {**cached["result"], "audit_id": audit_id, "cached_from": cached["id"]}
            deep = "done" if cached["status"] == "complete" else "available"
            db.create(audit_id, req.repo_url, repo_key, head_sha, req.run_kind, status=cached["status"],
                      phase_quick="done", phase_deep=deep, cached_from=cached["id"],
                      steps=cached["steps"], result=result)
            return {"id": audit_id, "status": cached["status"], "cached": True}
        running = db.find_in_progress(repo_key, head_sha)
        if running:  # same commit already being audited: follow that one
            return {"id": running["id"], "status": running["status"], "cached": False, "deduplicated": True}

    db.create(audit_id, req.repo_url, repo_key, head_sha, req.run_kind)
    queue = await queues.submit(audit_id, req.repo_url, req.run_kind, use_reserve=is_admin(x_admin_token))
    return {"id": audit_id, "status": "queued", "cached": False, "queue": queue}


@app.post("/api/audits/{audit_id}/deep", status_code=202,
          responses={404: {"description": "Audit not found"}, 409: {"description": "Deep check not possible"}})
def request_deep(audit_id: str, x_admin_token: str | None = Header(default=None)) -> dict:
    row = _get(audit_id)
    if row["status"] == "complete":
        return {"id": audit_id, "status": "complete", "queue": None}
    if row["status"] != "quick_ready":
        raise HTTPException(409, f"quick result isn't ready (status: {row['status']})")
    if row["phase_deep"] == "skipped":
        raise HTTPException(409, "nothing to verify: the repo couldn't be read")
    queue = queues.request_deep(audit_id, use_reserve=is_admin(x_admin_token))
    return {"id": audit_id, "status": row["status"], "phase_deep": "queued", "queue": queue}


@app.get("/api/audits/{audit_id}", responses={404: {"description": "Audit not found"}})
def get_audit(audit_id: str) -> dict:
    row = _get(audit_id)
    return {
        "id": row["id"],
        "repo_url": row["repo_url"],
        "status": row["status"],
        "phases": {"quick": row["phase_quick"], "deep": row["phase_deep"]},
        "queue": queues.position(audit_id),
        "cached": row["cached_from"] is not None,
        "created_at": row["created_at"],
        "updated_at": row["updated_at"],
        "steps": row["steps"],
        "result": row["result"],
        "error": row["error"],
    }


@app.post("/api/audits/{audit_id}/feedback", status_code=201, responses={404: {"description": "Audit not found"}})
def feedback(audit_id: str, req: FeedbackRequest) -> dict:
    _get(audit_id)
    db.add_feedback(audit_id, req.check_id, req.is_wrong, req.note)
    return {"ok": True}


def budget_state() -> str:
    """normal | busy (deep queue long) | cooling (public LLM budget used up: templates in use)."""
    if replay.mode() != "replay" and not POOL.budget(configured_models(), est=3000)["public_available"]:
        return "cooling"
    return "busy" if queues.busy() else "normal"


@app.get("/api/stats")
def stats() -> dict:
    return {**db.stats(), "budget_state": budget_state(), "deep_queue": queues.deep.length(),
            "deep_wait_s": round(queues.deep.avg_s * queues.deep.length()), "llm_mode": replay.mode()}


@app.get("/api/examples")
def examples() -> list[dict]:
    out = []
    for row in db.examples():
        r = row["result"] or {}
        out.append({"id": row["id"], "repo": (r.get("repo") or {}).get("full_name") or row["repo_url"],
                    "score": (r.get("score") or {}).get("score"), "roast": (r.get("verdict") or {}).get("roast"),
                    "style": (r.get("verdict") or {}).get("style"), "status": row["status"]})
    return out

